1	locals {
2	  audit_drop_condition = length(var.audit_drop_patterns) == 0 ? "true" : join(
3	    " && ",
4	    [for p in var.audit_drop_patterns : "!match(msg, r'${p}')"],
5	  )
6	
7	  rendered_values = var.additional_config != null ? yamlencode({ customConfig = var.additional_config }) : templatefile(
8	    "${path.module}/templates/values.yaml.tpl",
9	    {
10	      replicas                    = var.replicas
11	      requests_cpu                = var.resources_requests.cpu
12	      requests_memory             = var.resources_requests.memory
13	      limits_cpu                  = var.resources_limits.cpu
14	      limits_memory               = var.resources_limits.memory
15	      datadog_site                = var.datadog_site
16	      audit_drop_condition        = local.audit_drop_condition
17	      email_redaction_enabled     = var.email_redaction_enabled
18	      email_redaction_replacement = var.email_redaction_replacement
19	    },
20	  )
21	}
22	
23	resource "kubernetes_namespace_v1" "vector" {
24	  metadata {
25	    name = var.namespace
26	    labels = {
27	      "app.kubernetes.io/name"      = "vector"
28	      "app.kubernetes.io/component" = "telemetry-aggregator"
29	    }
30	  }
31	}
32	
33	resource "kubernetes_manifest" "datadog_external_secret" {
34	  manifest = {
35	    apiVersion = "external-secrets.io/v1"
36	    kind       = "ExternalSecret"
37	    metadata = {
38	      name      = "vector-datadog"
39	      namespace = kubernetes_namespace_v1.vector.metadata[0].name
40	    }
41	    spec = {
42	      refreshInterval = "1h"
43	      secretStoreRef = {
44	        kind = "ClusterSecretStore"
45	        name = var.external_secrets_cluster_store_name
46	      }
47	      target = {
48	        name           = "vector-datadog"
49	        creationPolicy = "Owner"
50	      }
51	      data = [{
52	        secretKey = "api_key"
53	        remoteRef = {
54	          key      = var.datadog_api_key_vault_path
55	          property = "api_key"
56	        }
57	      }]
58	    }
59	  }
60	
61	  wait {
62	    fields = {
63	      "status.conditions[0].type"   = "Ready"
64	      "status.conditions[0].status" = "True"
65	    }
66	  }
67	
68	  timeouts {
69	    create = "5m"
70	    update = "5m"
71	  }
72	}
73	
74	resource "helm_release" "vector" {
75	  name       = "vector"
76	  namespace  = kubernetes_namespace_v1.vector.metadata[0].name
77	  repository = "https://helm.vector.dev"
78	  chart      = "vector"
79	  version    = var.chart_version
80	
81	  values = [local.rendered_values]
82	
83	  set = [
84	    {
85	      name  = "image.repository"
86	      value = var.image
87	    },
88	    {
89	      name  = "image.tag"
90	      value = var.image_tag_version
91	    },
92	  ]
93	
94	  depends_on = [
95	    kubernetes_manifest.datadog_external_secret,
96	  ]
97	}
